DROP TABLE IF EXISTS `system_biz_module`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `system_biz_module` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `biz_type` varchar(64) NOT NULL COMMENT '业务类型',
  `name` varchar(128) NOT NULL COMMENT '显示名称',
  `list_template` json DEFAULT NULL,
  `form_template` json DEFAULT NULL,
  `detail_template` json DEFAULT NULL,
  `tree_template` json DEFAULT NULL,
  `layout_template` text COMMENT '布局模板 JSON',
  `ui_schema` text COMMENT 'UI Schema JSON',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除标记：0=正常 1=已删除',
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户编号',
  `creator` bigint DEFAULT NULL COMMENT '创建人',
  `updater` bigint DEFAULT NULL COMMENT '更新人',
  `template_id` varchar(64) DEFAULT NULL COMMENT '选用模板编号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `biz_type` (`biz_type`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='业务模块配置';
